begin;
delete from movimientos;
delete from honorarios;
delete from clientes;
select setval(pg_get_serial_sequence('clientes','id'), coalesce((select max(id) from clientes),1), true);
select setval(pg_get_serial_sequence('honorarios','id'), coalesce((select max(id) from honorarios),1), true);
select setval(pg_get_serial_sequence('movimientos','id'), coalesce((select max(id) from movimientos),1), true);
commit;